#!/usr/bin/env bun
// Per-folder index.md generator.
//   scripts/index.ts               regenerate index.md in every configured dir with >=1 note
//   scripts/index.ts <dir> [dir…]  regenerate index.md only for the named dir(s)
// Generated index.md files carry NO frontmatter (validator skips basename index.md) and start
// with the "generated by scripts/index.ts" header below — regenerate, don't hand-edit them.
import { readFileSync, writeFileSync, readdirSync, existsSync } from "node:fs";
import { resolve, join, relative, basename } from "node:path";
import { parseFrontmatter, extractField, extractTagsList, splitLines } from "./frontmatter.ts";
import { isRestricted, loadFromScript, resolveInside, runMain, toPosix } from "./config.ts";

const VAULT_ROOT = resolve(import.meta.dir, "..");
import { mdLink } from "./links.ts";

export interface NoteMeta {
  file: string; // filename incl. .md, e.g. "my-note.md"
  title: string; // H1 text, or filename (no ext) fallback
  description: string; // frontmatter 'description', blank if absent
  tags: string[]; // frontmatter tags, [] if absent
  type: string; // frontmatter 'type', blank if absent
  updated: string; // frontmatter 'updated', blank if absent
}

const GENERATED_HEADER = "<!-- generated by scripts/index.ts — regenerate, don't hand-edit -->";

/** First H1 ("# ...") line in a set of lines, trimmed. null if none. Deliberately does not
 *  match "## " (heading level 2+) — the regex requires whitespace immediately after the '#'. */
function extractH1(lines: string[]): string | null {
  for (const line of lines) {
    const m = /^#\s+(.+)$/.exec(line.trim());
    if (m) return m[1].trim();
  }
  return null;
}

/** Extract NoteMeta from a note file. Tolerant of missing/malformed frontmatter — never throws;
 *  falls back to filename-as-title and blank fields (e.g. raw clippings dropped into a vault dir). */
export function loadNoteMeta(path: string): NoteMeta {
  const file = basename(path);
  const fallbackTitle = file.replace(/\.md$/, "");
  let lines: string[];
  try {
    lines = splitLines(readFileSync(path, "utf8"));
  } catch {
    return { file, title: fallbackTitle, description: "", tags: [], type: "", updated: "" };
  }

  const parsed = parseFrontmatter(lines);
  if (!parsed) {
    return { file, title: extractH1(lines) ?? fallbackTitle, description: "", tags: [], type: "", updated: "" };
  }
  return {
    file,
    title: extractH1(parsed.body) ?? fallbackTitle,
    description: extractField(parsed.fm, "description") ?? "",
    tags: extractTagsList(parsed.fm) ?? [],
    type: extractField(parsed.fm, "type") ?? "",
    updated: extractField(parsed.fm, "updated") ?? "",
  };
}

/** All non-index .md notes directly inside `dir`, sorted by filename for deterministic input order. */
export function notesInDir(dir: string): NoteMeta[] {
  return readdirSync(dir)
    .filter((f) => f.endsWith(".md") && f !== "index.md")
    // Restricted notes never reach generated output: an index line would leak title and tags.
    .filter((f) => !isRestricted(toPosix(relative(VAULT_ROOT, join(dir, f))), readFileSync(join(dir, f), "utf8")))
    .sort()
    .map((f) => loadNoteMeta(join(dir, f)));
}

/** `pathPrefix` (e.g. "example-folder/") lets a shelf's index.md link into a subfolder note
 *  by its full relative path, while the subfolder's own index.md keeps bare links. The link
 *  text is `n.title` as loadNoteMeta already decided it (the H1 when present, else the file
 *  stem) — a Markdown link, unlike a wiki-link, always carries its text explicitly, so there is
 *  no separate bare-vs-aliased form to choose between. `"index.md"` below is a synthetic
 *  same-directory stand-in for the real index file being generated: hrefFor/mdLink only need
 *  the two paths' directories relative to each other, and pathPrefix already encodes that. */
function noteLine(n: NoteMeta, pathPrefix = ""): string {
  const link = mdLink(n.title, "index.md", pathPrefix + n.file);
  const meta: string[] = [];
  if (n.type) meta.push(`type: ${n.type}`);
  if (n.tags.length) meta.push(`tags: ${n.tags.join(", ")}`);
  if (n.updated) meta.push(`updated: ${n.updated}`);
  let line = `- ${link}`;
  if (n.description) line += ` — ${n.description}`;
  if (meta.length) line += ` (${meta.join(" · ")})`;
  return line;
}

// Subfolder names that mark a directory as an application tree / tooling cache rather than a
// notes folder — skipped entirely from subfolder indexing.
const SKIP_SUBFOLDER_NAMES = new Set([".venv", "__pycache__"]);

/** Immediate subfolders of `dir` that hold vault notes one level deep inside a semantic shelf
 * . Excludes application trees (a package.json or node_modules inside) and known
 *  tooling-cache dirs. Does not require the subfolder to contain any .md notes — callers decide
 *  whether an empty one is worth listing. */
export function noteSubfolders(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true })
    .filter((e) => e.isDirectory())
    .map((e) => e.name)
    .filter((name) => {
      if (SKIP_SUBFOLDER_NAMES.has(name)) return false;
      const sub = join(dir, name);
      if (existsSync(join(sub, "package.json"))) return false;
      if (existsSync(join(sub, "node_modules"))) return false;
      return true;
    })
    .sort();
}

/** Build full index.md markdown for one vault dir. Pure — same input always yields byte-identical
 *  output (no timestamps, no randomness, no filesystem-order dependence — callers sort notes/groups).
 *  "default": group by type (groups + header sorted alphabetically), reverse-chron by updated within
 *  a group. "alphabetical": flat list sorted by title (e.g. a folder of people). */
export interface SubfolderNotes {
  name: string; // subfolder name, e.g. "example-folder"
  notes: NoteMeta[]; // notes directly inside it (not recursive)
}

/** `subfolders`: rendered as `## <name>/` sections AFTER the type-grouped (or
 *  alphabetical) sections, in the order given — callers pass them pre-sorted by name. Empty
 *  subfolders are omitted by the caller before reaching here. */
export function buildIndex(
  dirName: string,
  notes: NoteMeta[],
  style: "default" | "alphabetical",
  subfolders: SubfolderNotes[] = [],
): string {
  const header = `${GENERATED_HEADER}\n\n# ${dirName}\n`;
  const subSections = subfolders.map(
    (s) => `\n## ${s.name}/\n\n` + s.notes.map((n) => noteLine(n, `${s.name}/`)).join("\n") + "\n",
  );

  if (notes.length === 0) {
    if (subSections.length === 0) return header + "\n_(no notes yet)_\n";
    return header + subSections.join("");
  }

  if (style === "alphabetical") {
    const sorted = [...notes].sort((a, b) => a.title.localeCompare(b.title));
    return header + "\n" + sorted.map((n) => noteLine(n)).join("\n") + "\n" + subSections.join("");
  }

  const groups = new Map<string, NoteMeta[]>();
  for (const n of notes) {
    const key = n.type || "untyped";
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key)!.push(n);
  }
  const sections = [...groups.keys()].sort().map((type) => {
    const items = groups.get(type)!
      .slice()
      .sort((a, b) => (b.updated || "").localeCompare(a.updated || "") || a.title.localeCompare(b.title));
    return `\n## ${type}\n\n` + items.map((n) => noteLine(n)).join("\n") + "\n";
  });
  return header + sections.join("") + subSections.join("");
}

function targetDirs(d: ReturnType<typeof loadFromScript>): string[] {
  return [...Object.values(d.SEMANTIC_DIRS), ...Object.values(d.EPISODIC_DIRS), ...d.cfg.extra_dirs];
}

function main() {
  const vaultRoot = resolve(import.meta.dir, "..");
  const d = loadFromScript(import.meta.dir);
  const configuredDirs = new Set(targetDirs(d));
  const styleMap: Record<string, string> = d.cfg.index_style ?? {};

  const args = process.argv.slice(2);
  const notesByDir = new Map<string, NoteMeta[]>();
  let relDirs: string[];
  if (args.length > 0) {
    relDirs = [];
    for (const a of args) {
      let full: string;
      try {
        full = resolveInside(vaultRoot, a); // a CLI dir arg must not escape the vault root
      } catch (e: any) {
        console.error(`error: ${e.message}`);
        process.exit(2);
      }
      const rel = relative(vaultRoot, full).replaceAll("\\", "/");
      if (configuredDirs.has(rel)) relDirs.push(rel);
    }
  } else {
    for (const rel of configuredDirs) {
      if (existsSync(join(vaultRoot, rel))) notesByDir.set(rel, notesInDir(join(vaultRoot, rel)));
    }
    relDirs = [...notesByDir].filter(([, notes]) => notes.length > 0).map(([rel]) => rel).sort();
  }

  let count = 0;
  for (const rel of relDirs) {
    const full = join(vaultRoot, rel);
    if (!existsSync(full)) continue;
    const style = styleMap[rel] === "alphabetical" ? "alphabetical" : "default";

    const subfolders: SubfolderNotes[] = [];
    for (const name of noteSubfolders(full)) {
      const subFull = join(full, name);
      const subNotes = notesInDir(subFull);
      if (subNotes.length === 0) continue;
      subfolders.push({ name, notes: subNotes });
      // The subfolder's own index.md — bare links, same "default" grouping as its parent shelf.
      writeFileSync(join(subFull, "index.md"), buildIndex(name, subNotes, "default"), "utf8");
      console.log(`✓ index.md → ${rel}/${name}/`);
      count++;
    }

    writeFileSync(join(full, "index.md"), buildIndex(rel, notesByDir.get(rel) ?? notesInDir(full), style, subfolders), "utf8");
    console.log(`✓ index.md → ${rel}/`);
    count++;
  }
  if (count === 0) console.log("no target directories with notes found");
}

if (import.meta.main) runMain(main);
